<template><div><div class="eyebrow">CATALOGUE</div><h1 class="page-title">Examinations</h1><p class="text-secondary">Search the examination catalogue and browse available slots.</p>
 <div class="card panel-card mb-4"><div class="card-body"><div class="row g-2"><div class="col-md-8"><input v-model="q" class="form-control" placeholder="Search by examination or course name" @input="load"></div><div class="col-md-4"><select v-model="type" class="form-select" @change="load"><option value="">All examination types</option><option>Viva</option><option>Practical</option><option>Project Demo</option><option>Assessment</option></select></div></div></div></div>
 <div v-if="error" class="alert alert-warning">{{error}}</div><div class="row g-3"><div v-for="e in exams" :key="e.id" class="col-md-6 col-xl-4"><div class="card exam-card h-100"><div class="card-body d-flex flex-column"><div class="d-flex justify-content-between mb-3"><span class="badge rounded-pill text-bg-light">{{e.examination_type}}</span><span class="small text-secondary">{{e.examination_status}}</span></div><h2 class="h5 fw-bold">{{e.examination_name}}</h2><p class="text-secondary small">{{e.course_code}} · {{e.course_name}}</p><p class="small">{{e.description||e.instructions||'Examination details will be provided by the course administrator.'}}</p><div class="mt-auto d-flex justify-content-between align-items-center"><span class="small text-secondary">{{e.duration}} min · {{e.maximum_marks}} marks</span><button class="btn btn-sm btn-outline-primary" @click="showSlots(e)">View slots</button></div></div></div></div></div>
 <div v-if="selected" class="modal-backdrop-custom"><div class="card slot-modal shadow-lg"><div class="card-body"><div class="d-flex justify-content-between"><h2 class="h5">{{selected.examination_name}} · Slots</h2><button class="btn-close" @click="selected=null"></button></div><div v-if="!slots.length" class="text-secondary py-3">No slots available for this examination.</div><div v-for="s in slots" :key="s.id" class="border rounded p-3 my-2 d-flex justify-content-between gap-3"><div><div class="fw-semibold">{{s.exam_date}} · {{s.start_time}}–{{s.end_time}}</div><div class="small text-secondary">{{s.examiner_name}} · {{s.available_seats}} seats</div></div><button class="btn btn-sm btn-primary" :disabled="role!=='student'||s.status!=='Available'||s.available_seats<1" @click="book(s)">Book</button></div><div v-if="message" class="alert alert-info mt-3 mb-0">{{message}}</div></div></div></div>
</div></template>
<script>
import {api} from '../services/api'
export default {data:()=>({exams:[],q:'',type:'',error:'',selected:null,slots:[],role:null,message:''}),async mounted(){try{this.role=(await api.get('/auth/me')).data.user.role}catch{}this.load()},methods:{
 async load(){try{this.exams=(await api.get('/examinations',{params:{q:this.q,type:this.type}})).data.items;this.error=''}catch(e){this.error=e.response?.data?.error||'Unable to load examinations'}},
 async showSlots(e){this.selected=e;this.message='';try{this.slots=(await api.get('/slots',{params:{examination_id:e.id,available:1}})).data.items}catch{this.slots=[]}},
 async book(s){try{await api.post(`/slots/${s.id}/book`);this.message='Booking confirmed!';await this.showSlots(this.selected)}catch(e){this.message=e.response?.data?.error||'Booking failed'}}
}}
</script>
